INSERT INTO checkup_programs (clinic_id, slug, name_ua, name_ru, gender, age_group, price_regular, price_discount, composition, is_specialized, is_active, sort_order, program_type, price_date, currency, details) SELECT id, 'anadolu-women-65-plus', 'Перевірка здоров’я – жінки від 65 років', 'ПРОВЕРКА ЗДОРОВЬЯ - женщины старше 65', 'female', '65+', 1935, 1935, $j$[{"group":"Кардиология","items":["ЭКГ","Эхокардиография","Компьютерная томография (КТ) коронарных артерий (определение уровня кальцификации)","Консультация кардиолога"]},{"group":"Гинекология и маммология","items":["УЗИ органов малого таза, молочных желез","Маммография","ПАП-тест","Анализ на онкомаркеры (СА-125, СА 15-3)","Консультация гинеколога"]},{"group":"Эндокринология","items":["УЗИ щитовидной железы","Анализ гормонов щитовидной железы (ТТГ, Т4 свободный, Т3 свободный)","Анализ на паратгормон и кальцитонин","Консультация эндокринолога"]},{"group":"Неврология","items":["МРТ головного мозга","Оценка когнитивных функций","Консультация невролога"]},{"group":"Офтальмология","items":["Проверка остроты зрения","Измерение внутриглазного давления","Осмотр глазного дна","Консультация офтальмолога"]},{"group":"Стоматология","items":["Панорамный снимок зубов","Консультация стоматолога"]},{"group":"Общая диагностика","items":["Общий и биохимический анализ крови","Анализ уровня витамина D, B12, фолиевой кислоты","Оценка липидного профиля","Анализ на гликированный гемоглобин","Общий анализ мочи","Анализ кала на скрытую кровь","Рентген грудной клетки","УЗИ органов брюшной полости","Денситометрия (оценка плотности костной ткани)","Оценка нутритивного статуса","Консультация по вакцинации","Заключительная консультация терапевта","Подробное заключение о состоянии здоровья и индивидуальные рекомендации"]}]$j$::jsonb, false, true, 0, 'clinic', '2026-11-16', 'USD', $j${"summary":"Комплексная диагностика для поддержания качества жизни в элегантном возрасте","duration":"2-3 дня","description":["Программа \"ПРОВЕРКА ЗДОРОВЬЯ - женщины старше 65\" в медицинском центре Анадолу предлагает всестороннее обследование, разработанное с учетом физиологических особенностей и потребностей женского организма в возрасте старше 65 лет. Наша цель - обеспечить раннее выявление возможных заболеваний, оценить общее состояние здоровья и разработать персонализированный план по поддержанию активного долголетия."],"goals":["Комплексная оценка состояния здоровья с учетом возрастных изменений","Ранняя диагностика и профилактика сердечно-сосудистых заболеваний","Выявление рисков остеопороза и других заболеваний опорно-двигательного аппарата","Скрининг онкологических заболеваний, характерных для женщин старшего возраста","Разработка индивидуальных рекомендаций по питанию, физической активности и образу жизни"],"preparation":[{"group":"За 3 дня до обследования","items":["Исключите из рациона продукты, вызывающие метеоризм (бобовые, капусту, свежие фрукты)","Прекратите прием препаратов железа и активированного угля","Для анализа кала на скрытую кровь: исключите красное мясо, печень, рыбу, помидоры, зеленые овощи, хрен, бананы, дыни"]},{"group":"За 24 часа","items":["Воздержитесь от алкоголя и интенсивных физических нагрузок","Не принимайте слабительные и мочегонные препараты"]},{"group":"За 12 часов","items":["Прекратите прием пищи","Пейте только воду"]},{"group":"За 8 часов","items":["Воздержитесь от курения","Не пейте кофе и другие стимулирующие напитки"]},{"group":"В день обследования","items":["Придите натощак","Возьмите с собой все имеющиеся медицинские документы и результаты предыдущих обследований","Наденьте удобную одежду, легко снимающуюся для обследований","Не используйте дезодорант или тальк в области груди и подмышек (для маммографии)"]},{"group":"Особые указания","items":["Сообщите врачу о принимаемых лекарствах, добавках и аллергических реакциях","Для некоторых УЗИ может потребоваться наполненный мочевой пузырь (уточните у администраторов клиники)","За 7 дней до анализа кала на скрытую кровь прекратите прием нестероидных противовоспалительных препаратов, если это возможно по состоянию здоровья","Для получения наиболее точных результатов гинекологических исследований рекомендуется проходить обследование в первой половине менструального цикла. При наличии менструации некоторые исследования могут быть перенесены"]}]}$j$::jsonb FROM clinics WHERE slug = 'anadolu-istanbul' ON CONFLICT (clinic_id, slug) DO NOTHING;
