ные риски и разработать индивидуальный план по поддержанию здоровья и активного образа жизни."],"goals":["Комплексная оценка состояния здоровья и выявление скрытых патологий","Ранняя диагностика и профилактика сердечно-сосудистых заболеваний","Скрининг онкологических заболеваний, характерных для женщин этого возраста","Оценка гормонального статуса и выявление нарушений обмена веществ","Анализ состава тела и разработка рекомендаций по питанию и физической активности Профилактика остеопороза и других возрастных изменений"],"preparation":[{"group":"За 24 часа","items":["Воздержитесь от алкоголя и интенсивных физических нагрузок","Не принимайте слабительные и мочегонные препараты"]},{"group":"За 12 часов","items":["Прекратите прием пищи","Пейте только воду"]},{"group":"За 8 часов","items":["Воздержитесь от курения","Не пейте кофе и другие стимулирующие напитки"]},{"group":"В день обследования","items":["Прийдите натощак","Возьмите с собой все имеющиеся медицинские документы и результаты предыдущих обследований","Наденьте удобную одежду, легко снимающуюся для обследований","Не используйте дезодорант или тальк в области груди и подмышек (для маммографии)"]},{"group":"Особые указания","items":["Сообщите врачу о принимаемых лекарствах, добавках и аллергических реакциях","Для получения наиболее точных результатов гинекологических исследований рекомендуется проходить обследование в первой половине менструального цикла","При наличии менструации некоторые исследования могут быть перенесены"]}]}$j$::jsonb FROM clinics WHERE slug = 'anadolu-istanbul' ON CONFLICT (clinic_id, slug) DO NOTHING;
